args.sql:
SELECT fin_ops_ref, ops_costs_usd, (transportcostsusd + storage_costs_usd + personnelcostsusd) as total_component_costs, 
       CASE WHEN ops_costs_usd = (transportcostsusd + storage_costs_usd + personnelcostsusd) THEN 'match' ELSE 'mismatch' END as check_match
FROM financials WHERE funding_state = 'Critical' LIMIT 10;

SELECT COUNT(DISTINCT o.opsregistry) FROM operations o 
JOIN financials f ON o.opsregistry = f.fin_ops_ref
WHERE f.funding_state = 'Critical';

SELECT COUNT(DISTINCT o.opsregistry) FROM operations o 
JOIN financials f ON o.opsregistry = f.fin_ops_ref
WHERE f.funding_state IN ('Critical', 'Limited');
